('b60dda6d-45fd-4bfa-97c2-d42394404815', 'Swimming with Wild Dolphins', '<p>Join&nbsp;us&nbsp;for&nbsp;an&nbsp;early&nbsp;morning&nbsp;boat&nbsp;trip&nbsp;to&nbsp;meet&nbsp;the&nbsp;wild&nbsp;spinner&nbsp;and&nbsp;bottlenose&nbsp;dolphins&nbsp;in&nbsp;their&nbsp;natural&nbsp;habitat&nbsp;along&nbsp;the&nbsp;West&nbsp;coast.</p> (Imported from JSON backup: TL_FULL_BACKUP_2026-05-16T15-20-55-935Z.json)', NULL, NULL, 4.5, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-19T16:13:26.599+00:00', '2026-05-19T16:13:26.599+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, false, 0, NULL, false, 'Limited Time', true, false, NULL, NULL, NULL, 12, '[]'::jsonb, NULL, 0, NULL),
('afec5406-4dfb-488e-a7c5-4dce7e4dc353', 'Ile aux Cerfs Catamaran Excursion with Lunch', '<p>Experience&nbsp;an&nbsp;unforgettable&nbsp;day&nbsp;at&nbsp;Ile&nbsp;aux&nbsp;Cerfs&nbsp;aboard&nbsp;a&nbsp;luxury&nbsp;catamaran&nbsp;cruise&nbsp;across&nbsp;Mauritius’&nbsp;stunning&nbsp;east&nbsp;coast&nbsp;lagoon.&nbsp;Enjoy&nbsp;crystal-clear&nbsp;waters,&nbsp;snorkeling&nbsp;sessions,&nbsp;delicious&nbsp;BBQ&nbsp;lunch,&nbsp;refreshing&nbsp;drinks,&nbsp;and&nbsp;lively&nbsp;island&nbsp;vibes&nbsp;while&nbsp;discovering&nbsp;one&nbsp;of&nbsp;the&nbsp;most&nbsp;beautiful&nbsp;beaches&nbsp;in&nbsp;Mauritius.&nbsp;Perfect&nbsp;for&nbsp;couples,&nbsp;families,&nbsp;and&nbsp;groups&nbsp;seeking&nbsp;relaxation,&nbsp;adventure,&nbsp;and&nbsp;breathtaking&nbsp;tropical&nbsp;scenery.</p>', 'Trou d''eau Douces', 'East Coast', 4.5, 'services/1778909082604-pzxwj7e55r.webp', '["bbq lunch","Soft Drinks & Beverages","Music & Entertainment","Waterfall Discovery Stop","Snorkeling Equipment","Visit to Ile aux Cerfs Island","Activities"]'::jsonb, 'activity', NULL, NULL, NULL, '2026-05-16T05:44:57.498+00:00', '2026-05-16T05:44:57.495+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, '["services/1778910145945-ln9jweau7z.jpg","services/1778910162711-9vl8wmqbnim.jpg","services/1778910170449-iu0z8ajej8.jpg","services/1778910182233-hv4g7wjfefp.jpg","services/1778910195958-icjqmos1qhd.webp","services/1778910209611-6gf0gn1pee.jpg","services/1778910225935-ixbg8735o5s.jpg","services/1778910233995-9sstwqvxcc.jpg","services/1778910247340-q85v4fivk3k.jpg","services/1778910262871-q0x3knqgx6m.jpg"]'::jsonb, '', '', NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, 'services/1778909063188-bn23qd9g16r.webp', false, 0, 'services/1778909069959-qzj5p887k7f.jpg', false, 'Limited Time', true, false, 'Sail across turquoise lagoons, enjoy BBQ lunch, snorkeling, music, and relax on the stunning Ile aux Cerfs.', NULL, NULL, 12, '[]'::jsonb, 'Sea', 0, NULL),
('d38f9018-55e1-4fef-b0c3-c71fb3e44fbb', 'Sea Diamond Boutique Hotel & Spa', '<p>Sea&nbsp;Diamond&nbsp;Boutique&nbsp;Hotel&nbsp;&amp;&nbsp;Spa&nbsp;is&nbsp;a&nbsp;five-star&nbsp;relaxed&nbsp;luxury&nbsp;boutique&nbsp;hotel&nbsp;nested&nbsp;on&nbsp;Calodyne&nbsp;Beach&nbsp;of&nbsp;the&nbsp;multiple&nbsp;turquoise&nbsp;colours&nbsp;of&nbsp;the&nbsp;Indian&nbsp;Ocean&nbsp;and&nbsp;overlooking&nbsp;the&nbsp;spectacular&nbsp;view&nbsp;of&nbsp;the&nbsp;five&nbsp;islets&nbsp;of&nbsp;the&nbsp;north-east&nbsp;of&nbsp;Mauritius.&nbsp;This&nbsp;new&nbsp;boutique&nbsp;hotel&nbsp;offers&nbsp;73&nbsp;luxurious&nbsp;Suites&nbsp;in&nbsp;lush&nbsp;greenery,&nbsp;2&nbsp;restaurants&nbsp;(main&nbsp;restaurant&nbsp;of&nbsp;150&nbsp;covers&nbsp;and&nbsp;a&nbsp;fine&nbsp;dining&nbsp;restaurant&nbsp;of&nbsp;30&nbsp;covers),&nbsp;a&nbsp;pool&nbsp;bar,&nbsp;a&nbsp;spa&nbsp;village,&nbsp;a&nbsp;gym,&nbsp;a&nbsp;library&nbsp;and&nbsp;a&nbsp;boathouse,&nbsp;ideal&nbsp;for&nbsp;a&nbsp;peaceful&nbsp;and&nbsp;relaxing&nbsp;beach&nbsp;holiday&nbsp;experience.</p><p></p><p>CHECK&nbsp;IN&nbsp;:&nbsp;14HRS</p><p>CHECK&nbsp;OUT&nbsp;:&nbsp;11HRS30</p>', 'Calodyne', 'North Coast', 4.5, 'services/1778227021234-6upq2x5t1wl.webp', '[]'::jsonb, 'hotel', NULL, NULL, NULL, '2026-05-08T07:15:47.624+00:00', '2026-05-09T05:02:09.412+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, '["services/1778224405227-iwt40dz99q.webp","services/1778224416590-5w1tp89jnrj.webp","services/1778224431486-3rdpdca5hky.webp","services/1778224446460-w1x96bauvoo.webp","services/1778224456598-nkxj2zy0pli.webp","services/1778224468172-zsr5d1rgtqh.webp","services/1778224487113-0gqrqmsqtudw.webp","services/1778224501164-ulxm56ws3xm.webp","services/1778224511394-4r89xnle0ij.webp","services/1778224530787-b6hlq4ua5pt.jpg"]'::jsonb, '', '', NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, 'services/1778302918437-ou0tf7lg9b.webp', false, 0, 'services/1778224323165-z4y5bvpz67e.jpg', false, 'Limite