INSERT INTO public."content_blocks" ("id", "page_slug", "section_key", "content", "updated_at")
VALUES
('05e4d624-ff37-46a7-8d3b-c3b8b1fc898f', 'home', 'section_1_services', '{"label":"Exclusive Collections","title":"Curated Travel <br/> Experiences","description":"Discover our range of hand-picked travel categories, from luxury stays to adventurous tours across the world''s most beautiful destinations."}'::jsonb, '2026-04-27T16:51:37.98844+00:00'),
('d05deab1-f23c-410a-9d43-4084e7eec41d', 'home', 'section_2_advantage', '{"label":"Accredited Excellence","stats":[{"label":"Years Experience","value":"29+"},{"label":"Happy Travelers","value":"50k+"}],"title":"Decades of Travel <br/> Excellence","description":"Since 1995, Travel Lounge has been the beacon of premium travel services in Mauritius. Our commitment to excellence is backed by IATA accreditation and multiple global awards, ensuring that every journey you embark on is safe, seamless, and extraordinary."}'::jsonb, '2026-04-27T16:51:38.387805+00:00'),
('afddc33c-5329-4d2d-80da-89fa0227b6d8', 'home', 'section_3_deals', '{"label":"Exclusive Offers","title":"Promotional Deals"}'::jsonb, '2026-04-27T16:51:38.706655+00:00'),
('8fbec57a-42d6-4c3c-86a8-3f6ecc678b44', 'home', 'section_4_partners', '{"label":"Our Strategic Partners"}'::jsonb, '2026-04-27T16:51:39.103811+00:00'),
('1d5d28f5-7d02-4f9f-ac00-029836302757', 'home', 'section_5_seo_content', '{"title":"Your Premier Boutique Travel Agency in Mauritius","paragraph_1":"Experience the pinnacle of <strong>Luxury Mauritius Travel</strong> with Travel Lounge. As the island''s leading boutique travel experts, we curate extraordinary journeys that go beyond standard hotel bookings. From the iconic shores of <strong>Le Morne</strong> to the hidden gems of the North Coast, our local concierge team ensures every detail is perfect.","paragraph_2":"Whether you are seeking <strong>all-inclusive holiday packages</strong>, exclusive catamaran cruises, or bespoke world tours departing from Mauritius, we offer IATA-accredited expertise since 1995. Our commitment to excellence has made us the trusted choice for thousands of travelers seeking authentic island experiences.","why_choose_list":["Tailor-made itineraries crafted by local Mauritius destination experts.","Exclusive access to boutique hotels and private villa collections.","24/7 personalized concierge support throughout your stay."],"why_choose_label":"Why Choose Our Agency?"}'::jsonb, '2026-04-27T16:54:22.738359+00:00'),
('8fcec791-45f1-45e6-99bd-95101b7c6f70', 'home', 'section_6_news', '{"label":"Travel Insights","title":"Latest from the <br/> <span class=''text-red-600 underline decoration-red-600/20 underline-offset-8''>Insider Lounge</span>"}'::jsonb, '2026-04-27T16:56:01.26193+00:00'),
('37d09166-ea01-4b8c-ac52-dee9a40209e0', 'about', 'section_1_hero', '{"badge":"Since 1995","image":"https://images.unsplash.com/photo-1544644181-1484b3fdfc62?q=80&w=2070&auto=format&fit=crop","title":"Defining the Art of <br/> Boutique Travel","description":"We don''t just book trips; we craft legacies. Travel Lounge is Mauritius''s premier gateway to extraordinary global experiences and authentic island discoveries."}'::jsonb, '2026-04-27T16:58:27.320372+00:00'),
('487300d3-e0f3-4f54-8036-98b83069c155', 'about', 'section_2_identity', '{"quote":"Our mission is to transform every journey into a masterpiece of memories, blending luxury with authentic local soul.","title":"Mauritius''s Most <br/> Trusted Travel Experts","description":"With over 29 years of excellence, Travel Lounge stands as a pillar of trust in the Mauritian travel landscape. Our boutique approach ensures that every client receives personalized care, exclusive access, and the IATA-accredited expertise they deserve.","stats_label":"Years of Excellence","stats_value":"29+"}'::jsonb, '2026-04-27T16:58:27.624203+00:00'),
('da29094e-e348-4daa-af0e-fe9a95be5941', 'visa-services', 'cta', '{"title":"Need a Visa for your Next Trip?","description":"<p>Whether&nbsp;it&#39;s&nbsp;for&nbsp;the&nbsp;USA,&nbsp;UK,&nbsp;Schengen&nbsp;Area,&nbsp;or&nbsp;Turkey,&nbsp;our&nbsp;specialized&nbsp;visa&nbsp;department&nbsp;is&nbsp;here&nbsp;to&nbsp;ensure&nbsp;a&nbsp;high-success&nbsp;application&nbsp;process.</p>","primary_label":"Contact Visa Expert","secondary_label":"View All Destinations"}'::jsonb, '2026-05-03T08:44:39.038608+00:00'),
('adf5ed33-1676-46d1-83f6-a5c711802320', 'visa-services', 'hero', '{"badge":"Expert Assistance","image":"https://images.unsplash.com/photo-1544027993-37dbfe43562a?q=80&w=2070&auto=format&fit=crop","title":"<p>Seamless&nbsp;</p><p>Visa&nbsp;Solutions.</p>","subtitle":"Global Access Made Simple"}'::jsonb, '2026-05-03T08:44:44.14265+00:00'),
('0e70cce6-0b1c-47c2-bb80-76f0b7e9943a', 'visa-services', 'sidebar', '{"title":"Why Trust Travel Lounge?","features":[{"desc":"Decades of professional excellence in global travel documentation.","icon":"ShieldCheck","title":"IATA Certified"},{"desc":"Dedicated experts for USA, Canada, and European visas.","icon":"UserCheck","title":"Specialized Desk"},{"desc":"From the first inquiry to the final passport collection.","icon":"RefreshCw","title":"End-to-End Support"}],"notice_title":"Important Notice","notice_content":"<p>While&nbsp;we&nbsp;provide&nbsp;expert&nbsp;guidance&nbsp;to&nbsp;maximize&nbsp;your&nbsp;success&nbsp;rate,&nbsp;visa&nbsp;issuance&nbsp;is&nbsp;the&nbsp;sole&nbsp;prerogative&nbsp;of&nbsp;the&nbsp;respective&nbsp;diplomatic&nbsp;missions.&nbsp;Fees&nbsp;are&nbsp;non-refundable&nbsp;regardless&nbsp;of&nbsp;the&nbsp;outcome.</p>","disclaimer_label":"Visa Terms & Conditions"}'::jsonb, '2026-05-03T08:44:50.567671+00:00'),
('2a922d70-0a6a-4aa7-a216-375e3e0df5b4', 'team', 'hero', '{"badge":"Our People","image":"","title":"<p>Meet&nbsp;the&nbsp;</p><p>Experts.</p>","description":"<p></p>"}'::jsonb, '2026-05-14T05:31:05.618+00:00');

